bool echoLineToMessageSink = false;
// if we have a channel listener, then just spool the message
// directly to the listener
if (m_channelListener) {
  uint32_t count = 0;
  if (m_channelOutputStream) {
    nsresult rv = m_channelOutputStream->Write(line, byteCount, &count);
    NS_ASSERTION(count == byteCount,
                 "IMAP channel pipe couldn't buffer entire write");
    if (NS_SUCCEEDED(rv)) {
      rv = m_channelListener->OnDataAvailable(
          m_mockChannel, m_channelInputStream, 0, count);
      NS_ENSURE_SUCCESS_VOID(rv);
    }
    // else some sort of explosion?
  }
}
if (m_runningUrl)
  m_runningUrl->GetStoreResultsOffline(&echoLineToMessageSink);

m_bytesToChannel += byteCount;

mbox = await IOUtils.readUTF8(inbox.filePath.path);
info(mbox);
Assert.ok(
  !mbox.includes(`Subject: ${testMessage.subject}`),
  "the new message should not be added to the mbox file"
);

// Fetch the message to "read" it. It still shouldn't have the flag or the
// token, or exist in the mbox.

const uri = inbox.getUriForMsg(messages[2]);
const service = MailServices.messageServiceFromURI(uri);

urlListener = new PromiseTestUtils.PromiseUrlListener();
service.loadMessage(uri, null, null, urlListener, false);
await urlListener.promise;
